#import <Metal/Metal.h>
#import <Foundation/Foundation.h>
#include <math.h>
#include <stdio.h>
#include <string.h>

static NSString *src(void){return @"#include <metal_stdlib>\nusing namespace metal;\n"
"kernel void k(texture2d<float,access::sample> t [[texture(0)]], sampler s [[sampler(0)]], device float4 *o [[buffer(0)]], uint i [[thread_position_in_grid]]) { float2 u[4]={float2(-.25,.25),float2(.25,.25),float2(.75,.75),float2(1.25,.25)}; o[i]=t.sample(s,u[i],level(0)); }\n";}
static const char *nm(MTLSamplerAddressMode m){return m==MTLSamplerAddressModeClampToZero?"zero":m==MTLSamplerAddressModeClampToEdge?"edge":"repeat";}
int main(void){@autoreleasepool{id<MTLDevice>d=MTLCreateSystemDefaultDevice();NSError*e=nil;id<MTLLibrary>l=[d newLibraryWithSource:src() options:nil error:&e];id<MTLComputePipelineState>p=[d newComputePipelineStateWithFunction:[l newFunctionWithName:@"k"] error:&e];if(!p){fprintf(stderr,"PIPELINE %s\n",e.localizedDescription.UTF8String);return 2;}MTLTextureDescriptor*td=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:2 height:2 mipmapped:NO];td.storageMode=MTLStorageModeShared;td.usage=MTLTextureUsageShaderRead;id<MTLTexture>t=[d newTextureWithDescriptor:td];uint8_t px[16]={255,0,0,255,0,255,0,255,0,0,255,255,255,255,255,255};[t replaceRegion:MTLRegionMake2D(0,0,2,2) mipmapLevel:0 withBytes:px bytesPerRow:8];id<MTLBuffer>o=[d newBufferWithLength:24*sizeof(simd_float4) options:MTLResourceStorageModeShared];MTLSamplerAddressMode ms[3]={MTLSamplerAddressModeClampToZero,MTLSamplerAddressModeClampToEdge,MTLSamplerAddressModeRepeat};for(int a=0;a<3;a++)for(int f=0;f<2;f++){MTLSamplerDescriptor*s=[MTLSamplerDescriptor new];s.sAddressMode=s.tAddressMode=ms[a];s.minFilter=s.magFilter=f?MTLSamplerMinMagFilterLinear:MTLSamplerMinMagFilterNearest;s.mipFilter=MTLSamplerMipFilterNotMipmapped;id<MTLSamplerState>ss=[d newSamplerStateWithDescriptor:s];id<MTLCommandBuffer>c=[[d newCommandQueue] commandBuffer];id<MTLComputeCommandEncoder>x=[c computeCommandEncoder];[x setComputePipelineState:p];[x setTexture:t atIndex:0];[x setSamplerState:ss atIndex:0];[x setBuffer:o offset:(a*2+f)*4*sizeof(simd_float4) atIndex:0];[x dispatchThreads:MTLSizeMake(4,1,1) threadsPerThreadgroup:MTLSizeMake(4,1,1)];[x endEncoding];[c commit];[c waitUntilCompleted];if(c.status!=MTLCommandBufferStatusCompleted||c.error){fprintf(stderr,"COMMAND_FAIL\n");return 3;}printf("CASE mode=%s filter=%s",nm(ms[a]),f?"linear":"nearest");simd_float4*q=(simd_float4*)o.contents+(a*2+f)*4;for(int i=0;i<4;i++){printf(" %.6g,%.6g,%.6g,%.6g",q[i].x,q[i].y,q[i].z,q[i].w);if(!isfinite(q[i].x)||!isfinite(q[i].y)||!isfinite(q[i].z)||!isfinite(q[i].w))return 4;}puts("");}printf("DEVICE %s\nRESULT ok=1\n",d.name.UTF8String);return 0;}}
